import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0010: Why Dashboard is Off by Default","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0010-why-dashboard-off-by-default.md","filePath":"adr/ADR-0010-why-dashboard-off-by-default.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0010-why-dashboard-off-by-default.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0010-why-dashboard-is-off-by-default" tabindex="-1">ADR-0010: Why Dashboard is Off by Default <a class="header-anchor" href="#adr-0010-why-dashboard-is-off-by-default" aria-label="Permalink to “ADR-0010: Why Dashboard is Off by Default”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/dashboard-cli-config.md §9/§10, roadmap P4</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>The Dashboard is a management plane: it can see all resource health and trigger recovery operations. A self-healing engine with a default listening port is a persistent management entry on every target machine — exactly the attack surface a self-healing system should not have. P0/P1 goals (core recovery loop) require no UI.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The Dashboard is a <strong>disabled by default</strong> optional component: when not enabled there are zero listening ports and zero HTTP code paths (acceptance: closed = no port, unavailability does not affect core, does not bypass the Core Engine, high-risk still goes through unified authorization audit). Before enabling, HTTP transport security (auth, CSRF, bind address, read-only semantics) must be centrally hardened (with the toolbox transport security, ADR-0015).</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>On by default</strong>: every machine has a persistent management plane; home/router deployments (OpenWrt) are especially dangerous.</li><li><strong>CLI only, no Dashboard</strong>: the CLI already covers status/runs/incidents/notify/graph; deferring the UI loses no core capability.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: zero new attack surface by default; the core stays headless and embeddable; UI iteration never touches recovery semantics. Cons: early visibility relies on the CLI; operators need documentation.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>All P4 Dashboard entries are accepted under the &quot;disabled by default&quot; prerequisite.</li><li>The P4 authorization UI reuses the core&#39;s authorization audit, not a custom permission model.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};